+
+# --- Ternary ---
+
+# (23) select_f32: select with f32 pred (converts back to pred internally)
+# In NKI this maps to nl.where()
+# Pattern: (select (convert_? ?a) ?b ?c) -- the convert goes f32 -> pred
+instr = nki.add_instruction("select_f32", ["n"], ["sbuf_pred", "sbuf_true", "sbuf_false", "sbuf_out"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_pred"], [128, "@c.n"]],
+                  ["sbuf", [0, "@a.sbuf_true"], [128, "@c.n"]],
+                  ["sbuf", [0, "@a.sbuf_false"], [128, "@c.n"]]])
