+
+
+# --- Compare ---
+
+# (24) compare_f32: compare two f32 tensors, output f32 (via convert of pred)
+# In NKI this maps to nl.less() with a convert to f32
+# Pattern: (convert_? (compare_? ?a ?b)) -- matches after ir2ir rule 19 introduces convert
+instr = nki.add_instruction("compare_f32", ["n"], ["sbuf_a", "sbuf_b", "sbuf_out"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_a"], [128, "@c.n"]],
+                  ["sbuf", [0, "@a.sbuf_b"], [128, "@c.n"]]])
+instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+instr.add_semantics("""
+ENTRY compare_f32 {
+    %In1 = f32[128, `@c.n`] parameter(0);
+    %In2 = f32[128, `@c.n`] parameter(1);
+    %cmp = pred[128, `@c.n`] compare(%In1, %In2);
+    ROOT %Out0 = f32[128, `@c.n`] convert(%cmp);
+}
+""")
+
+
+# (26) store_1d_f32: store 1D f32[128] result to HBM
+# In NKI this maps to nl.store() of a 1D tensor (e.g. reduce output)
+instr = nki.add_instruction("store_1d_f32", [], ["hbm_addr", "sbuf_addr"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_addr"], [128, 1]]])
+instr.set_outputs([["d0", ["@a.hbm_addr"], ["512"]]])
+instr.add_semantics("""
+ENTRY store_1d_f32 {
+    %In1 = f32[128] parameter(0);
+    %r1 = u8[128, 4] bitcast_convert(%In1);
+    ROOT %Out0 = u8[512] reshape(%r1);
+}
+""")
+
+
+# --- Typed movement families (s32/u16/u8/pred; u32 above) ---
+# SBUF tiles carry the ROOT dtype of the producing instruction; one f32 SBUF
+# cell is accounted per element regardless of width.
+# In NKI these map to nl.load / nl.store / nl.copy with typed tiles.
+
+TYPED = [("s32", 4), ("u16", 2), ("u8", 1), ("pred", 1)]
+
+# The initializer's byte view omits the trailing size dim for 1-byte dtypes.
+def _bview(dims, sz):
+    return f"{dims}, {sz}" if sz != 1 else dims
+
+for _t, _sz in TYPED:
+    instr = nki.add_instruction(f"load_sbuf_{_t}", ["n"], ["hbm_addr", "sbuf_addr"])
+    instr.set_inputs([["d0", ["@a.hbm_addr"], [f"@c.n * {128 * _sz}"]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_addr"], [128, "@c.n"]]])
+    instr.add_semantics(f"""
+ENTRY load_sbuf_{_t} {{
+    %In1 = u8[`@c.n * {128 * _sz}`] parameter(0);
+    %r1 = u8[{_bview("128, `@c.n`", _sz)}] reshape(%In1);
+    ROOT %Out0 = {_t}[128, `@c.n`] bitcast_convert(%r1);
+}}
+""")
+
+    instr = nki.add_instruction(f"store_sbuf_{_t}", ["n"], ["hbm_addr", "sbuf_addr"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_addr"], [128, "@c.n"]]])
+    instr.set_outputs([["d0", ["@a.hbm_addr"], [f"@c.n * {128 * _sz}"]]])
+    instr.add_semantics(f"""
+ENTRY store_sbuf_{_t} {{
+    %In1 = {_t}[128, `@c.n`] parameter(0);
+    %r1 = u8[{_bview("128, `@c.n`", _sz)}] bitcast_convert(%In1);
+    ROOT %Out0 = u8[`@c.n * {128 * _sz}`] reshape(%r1);
+}}
+""")
+
+    instr = nki.add_instruction(f"store_1d_{_t}", [], ["hbm_addr", "sbuf_addr"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_addr"], [128, 1]]])
+    instr.set_outputs([["d0", ["@a.hbm_addr"], [f"{128 * _sz}"]]])
+    instr.add_semantics(f"""
+ENTRY store_1d_{_t} {{
+    %In1 = {_t}[128] parameter(0);
+    %r1 = u8[{_bview("128", _sz)}] bitcast_convert(%In1);
+    ROOT %Out0 = u8[{128 * _sz}] reshape(%r1);
+}}
+""")
+
+# store_1d_u32: 1D u32[128] result to HBM
+instr = nki.add_instruction("store_1d_u32", [], ["hbm_addr", "sbuf_addr"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_addr"], [128, 1]]])
+instr.set_outputs([["d0", ["@a.hbm_addr"], ["512"]]])
+instr.add_semantics("""
+ENTRY store_1d_u32 {
+    %In1 = u32[128] parameter(0);
+    %r1 = u8[128, 4] bitcast_convert(%In1);
+    ROOT %Out0 = u8[512] reshape(%r1);
+}
+""")
+
+# broadcast_load_<t>: load [1,n] from HBM, broadcast to [128,n] in sbuf
+# In NKI this maps to nl.load() with broadcast along par_dim
+for _t, _sz in [("u32", 4), ("s32", 4), ("u16", 2), ("u8", 1), ("pred", 1)]:
+    _bytes = f"@c.n * {_sz}" if _sz > 1 else "@c.n"
+    instr = nki.add_instruction(f"broadcast_load_{_t}", ["n"], ["hbm_addr", "sbuf_out"])
+    instr.set_inputs([["d0", ["@a.hbm_addr"], [_bytes]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+    instr.add_semantics(f"""
+ENTRY broadcast_load_{_t} {{
+    %In1 = u8[`{_bytes}`] parameter(0);
+    %r1 = u8[{_bview("1, `@c.n`", _sz)}] reshape(%In1);
+    %a = {_t}[1, `@c.n`] bitcast_convert(%r1);
+    ROOT %Out0 = {_t}[128, `@c.n`] broadcast(%a), dimensions={{0,1}};
+}}
+""")
+
+# copy_<t>: copy typed data within sbuf
+for _t in ["s32", "pred"]:
+    instr = nki.add_instruction(f"copy_{_t}", ["n"], ["sbuf_in", "sbuf_out"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_in"], [128, "@c.n"]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+    instr.add_semantics(f"""
+ENTRY copy_{_t} {{
+    %In1 = {_t}[128, `@c.n`] parameter(0);
+    ROOT %Out0 = {_t}[128, `@c.n`] copy(%In1);
+}}
+""")
+
+
+# --- Typed elementwise ---
+# In NKI: nl.bitwise_and/or/xor (bitvec, exact), nl.logical_and for pred,
+# nl.add / nl.multiply with integer dtypes.
+
+for _name, _op, _t in [
+    ("and_u32", "and", "u32"), ("or_u32", "or", "u32"), ("xor_u32", "xor", "u32"),
+    ("and_s32", "and", "s32"), ("and_pred", "and", "pred"),
+    ("add_u32", "add", "u32"), ("add_s32", "add", "s32"),
+    ("multiply_u32", "multiply", "u32"),
