+    instr = nki.add_instruction(_name, ["n"], ["sbuf_a", "sbuf_b", "sbuf_out"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_a"], [128, "@c.n"]],
+                      ["sbuf", [0, "@a.sbuf_b"], [128, "@c.n"]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+    instr.add_semantics(f"""
+ENTRY {_name} {{
+    %In1 = {_t}[128, `@c.n`] parameter(0);
+    %In2 = {_t}[128, `@c.n`] parameter(1);
+    ROOT %Out0 = {_t}[128, `@c.n`] {_op}(%In1, %In2);
+}}
+""")
+
+
+
+# --- Iota ---
+# nisa.iota writes the index pattern straight to SBUF, where folding it to an HBM
