+
+
+# --- Typed compare (LT) and select ---
+# In NKI: nl.less with typed operands; nl.where with a bool tile.
+
+for _t in ["s32", "u32", "f32"]:
+    _name = f"compare_{_t}_pred" if _t == "f32" else f"compare_{_t}"
+    instr = nki.add_instruction(_name, ["n"], ["sbuf_a", "sbuf_b", "sbuf_out"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_a"], [128, "@c.n"]],
