+    instr.add_semantics(f"""
+ENTRY {_name} {{
+    %In1 = {_t}[128, `@c.n`] parameter(0);
+    %In2 = {_t}[128, `@c.n`] parameter(1);
+    ROOT %Out0 = pred[128, `@c.n`] compare(%In1, %In2);
+}}
+""")
+
+# select_pred: select with a native pred condition
+instr = nki.add_instruction("select_pred", ["n"], ["sbuf_pred", "sbuf_true", "sbuf_false", "sbuf_out"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_pred"], [128, "@c.n"]],
+                  ["sbuf", [0, "@a.sbuf_true"], [128, "@c.n"]],
+                  ["sbuf", [0, "@a.sbuf_false"], [128, "@c.n"]]])
+instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+instr.add_semantics("""
+ENTRY select_pred {
+    %In1 = pred[128, `@c.n`] parameter(0);
+    %In2 = f32[128, `@c.n`] parameter(1);
+    %In3 = f32[128, `@c.n`] parameter(2);
+    ROOT %Out0 = f32[128, `@c.n`] select(%In1, %In2, %In3);
+}
+""")
+
+
+# --- Typed reductions (free dim) ---
+# In NKI: nisa.tensor_reduce(op=np.bitwise_or/np.bitwise_and/np.add, axis=[1]).
+
+for _name, _op, _t in [
+    ("reduce_or_u16", "reduce_or", "u16"), ("reduce_or_u8", "reduce_or", "u8"),
+    ("reduce_and_pred", "reduce_and", "pred"), ("reduce_add_s32", "reduce_add", "s32"),
+]:
+    instr = nki.add_instruction(_name, ["n"], ["sbuf_in", "sbuf_out"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_in"], [128, "@c.n"]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, 1]]])
+    instr.add_semantics(f"""
+ENTRY {_name} {{
+    %In1 = {_t}[128, `@c.n`] parameter(0);
+    ROOT %Out0 = {_t}[128] {_op}(%In1), dimensions={{1}};
+}}
+""")
+
+
+# --- Typed converts ---
+# In NKI: nl.copy(dtype=...) casts; pred results via nl.not_equal against 0.
+# The int<->f32 pairs are what make ir2ir rules 20-22 (shift-as-pow) selectable.
+
+for _src, _dst in [
+    ("pred", "u32"), ("u32", "pred"), ("u32", "u16"), ("u16", "u32"),
+    ("u32", "u8"), ("u8", "u32"), ("pred", "f32"),
+    ("u32", "f32"), ("f32", "u32"), ("s32", "f32"), ("f32", "s32"),
+]:
+    instr = nki.add_instruction(f"convert_{_src}_{_dst}", ["n"], ["sbuf_in", "sbuf_out"])
+    instr.set_inputs([["sbuf", [0, "@a.sbuf_in"], [128, "@c.n"]]])
+    instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+    instr.add_semantics(f"""
+ENTRY convert_{_src}_{_dst} {{
+    %In1 = {_src}[128, `@c.n`] parameter(0);
+    ROOT %Out0 = {_dst}[128, `@c.n`] convert(%In1);
+}}
+""")
+
+
+# --- Slice ---
+# Halve a [128,256] tile along the free dim: `_hi` takes columns 128..255.
+# In NKI these map to nl.copy of a sliced tile view.
+# The bounds are literal, so each rule only matches its own offset.
+
+for _t in ["f32", "u32"]:
+    for _suffix, _cols in [("", "0:128"), ("_hi", "128:256")]:
+        instr = nki.add_instruction(f"slice_copy_{_t}{_suffix}", [], ["sbuf_in", "sbuf_out"])
+        instr.set_inputs([["sbuf", [0, "@a.sbuf_in"], [128, 256]]])
+        instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, 128]]])
+        instr.add_semantics(f"""
+ENTRY slice_copy_{_t}{_suffix} {{
+    %In1 = {_t}[128, 256] parameter(0);
+    ROOT %Out0 = {_t}[128, 128] slice(%In1), slice={{[0:128:1], [{_cols}:1]}};
+}}
+""")
+
+
+# --- Tensor Engine (PSUM) ---
+# PSUM as f32: partition_dim=128, free_dim=4096 f32 elements (=16384 bytes).
+# The Tensor Engine reads both matmul operands from SBUF and writes PSUM only;
+# its accumulation and results are always f32.
+
+nki.add_data_model("psum", [128, 4096], [], "f32")
+
+# nc_matmul: stationary^T @ moving on the 128x128 systolic array, SBUF -> PSUM
+# In NKI this maps to nisa.nc_matmul(stationary, moving); the contraction
+# (partition) axis is <=128, the stationary free axis <=128, the moving <=512.
+instr = nki.add_instruction("nc_matmul", ["m", "n"], ["sbuf_stat", "sbuf_mov", "psum_out"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_stat"], [128, "@c.m"]],
+                  ["sbuf", [0, "@a.sbuf_mov"], [128, "@c.n"]]])
+instr.set_outputs([["psum", [0, "@a.psum_out"], ["@c.m", "@c.n"]]])
+instr.add_semantics("""
+ENTRY nc_matmul {
+    %In1 = f32[128, `@c.m`] parameter(0);
+    %In2 = f32[128, `@c.n`] parameter(1);
+    %t = f32[`@c.m`, 128] transpose(%In1), dimensions={1,0};
+    ROOT %Out0 = f32[`@c.m`, `@c.n`] dot(%t, %In2);
+}
+""")
+
+# nc_transpose: partition/free transpose on the Tensor Engine, SBUF -> PSUM
+# In NKI this maps to nisa.nc_transpose(data), a matmul against the identity.
+instr = nki.add_instruction("nc_transpose", ["n"], ["sbuf_in", "psum_out"])
+instr.set_inputs([["sbuf", [0, "@a.sbuf_in"], [128, "@c.n"]]])
+instr.set_outputs([["psum", [0, "@a.psum_out"], ["@c.n", 128]]])
+instr.add_semantics("""
+ENTRY nc_transpose {
+    %In1 = f32[128, `@c.n`] parameter(0);
+    ROOT %Out0 = f32[`@c.n`, 128] transpose(%In1), dimensions={1,0};
+}
+""")
+
+# copy_psum_sbuf: drain a PSUM tile back into SBUF
+# In NKI this maps to nl.copy(); the Vector Engine can read PSUM.
+instr = nki.add_instruction("copy_psum_sbuf", ["n"], ["psum_in", "sbuf_out"])
+instr.set_inputs([["psum", [0, "@a.psum_in"], [128, "@c.n"]]])
+instr.set_outputs([["sbuf", [0, "@a.sbuf_out"], [128, "@c.n"]]])
+instr.add_semantics("""
+ENTRY copy_psum_sbuf {
+    %In1 = f32[128, `@c.n`] parameter(0);
+    ROOT %Out0 = f32[128, `@c.n`] copy(%In1);
+}
+""")
+
+
+generate_backend(nki)

