+use std::collections::HashSet;
+
+use crate::ir::pii::{PiiGraph, PiiId, PiiNode};
+
+/// Give every extra use of an in-place operand its own copy of the producing node.
+pub fn fix_inplace(pii: &mut PiiGraph) {
+    let root_id = pii.root;
+    let mut visited: HashSet<PiiId> = HashSet::new();
+    dfs(pii, root_id, &mut visited);
+    remove_dead_nodes(pii);
+}
+
+/// Uses, not users: `f(x, x)` is one user but two uses, and still needs a copy.
+fn count_uses(pii: &PiiGraph, target: PiiId) -> usize {
+    pii.nodes
+        .values()
+        .map(|n| n.children.iter().filter(|c| **c == target).count())
+        .sum()
+}
+
+fn dfs(pii: &mut PiiGraph, node_id: PiiId, visited: &mut HashSet<PiiId>) {
+    if !visited.insert(node_id) {
+        return;
+    }
+
+    let inplace = pii.nodes[&node_id].op.inplace_children();
+    let children = pii.nodes[&node_id].children.clone();
+
+    for (i, &child_id) in children.iter().enumerate() {
+        // a copy is a node copy, not a storage copy, so never copy a pinned address
+        let pinned = pii.nodes[&child_id].hbm_offset.is_some();
+        if inplace[i] && !pinned && count_uses(pii, child_id) > 1 {
+            let new_id = copy_node(pii, child_id);
+            pii.nodes.get_mut(&node_id).unwrap().children[i] = new_id;
+            dfs(pii, new_id, visited);
+        } else {
+            dfs(pii, child_id, visited);
+        }
+    }
+}
+
+/// Duplicate a node under the next free copy index of its own node index.
+fn copy_node(pii: &mut PiiGraph, id: PiiId) -> PiiId {
+    let node = pii.nodes[&id].clone();
+    let next_copy = pii
+        .nodes
+        .keys()
+        .filter(|k| k.0 == id.0)
+        .map(|k| k.1)
+        .max()
+        .unwrap()
+        + 1;
+    let new_id = PiiId(id.0, next_copy);
+    pii.nodes.insert(new_id, PiiNode { id: new_id, ..node });
+    new_id
+}
+
+fn remove_dead_nodes(pii: &mut PiiGraph) {
+    let root_id = pii.root;
+    loop {
+        let mut used: HashSet<PiiId> = HashSet::new();
+        used.insert(root_id);
+        for node in pii.nodes.values() {
+            for &child in &node.children {
+                used.insert(child);
+            }
+        }
+        let before = pii.nodes.len();
+        pii.nodes.retain(|id, _| used.contains(id));
+        if pii.nodes.len() == before {
+            break;
+        }
+    }
+}

