+            ttile,
+            source,
+            dimensions,
+        } => {
+            add_reverse(tsymbol, ttype, tshape, source, dimensions, egraph, table);
+            if parsing_root {
+                add_root_operations(tsymbol, ttype, tshape, ttile, egraph, table, root);
