+/// The payload is the result shape, which materializes as a right-aligned
+/// broadcast; an axis map that is not right-aligned is appended after a `;`.
+fn add_broadcast(
+    tsymbol: &str,
+    ttype: &str,
+    tshape: &str,
+    source: &str,
+    dimensions: &[usize],
+    egraph: &mut EGraph<TensorOp, TensorInfo>,
+    table: &mut EggSymbolTable,
+) {
+    let dtype: Dtype = ttype.into();
+    let shape = shape_to_vec(tshape);
+
+    let src_rank = egraph[*table.get(source).unwrap()].data.shape.len();
+    let right_aligned: Vec<usize> = (shape.len().saturating_sub(src_rank)..shape.len()).collect();
+    let payload = if dimensions.is_empty() || dimensions == right_aligned {
+        tshape.to_string()
+    } else {
+        format!("{};{}", tshape, dimensions.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(","))
+    };
+
+    let node = egraph.add(TensorOp::OpBroadcast(
+        payload,
+        [*table.get(source).unwrap()],
+    ));
+
+    egraph.set_analysis_data(
+        node,
+        TensorInfo {
+            shape: shape.clone(),
+            dtype,
+            is_const: false,
+        },
+    );
+
+    table.insert(tsymbol.to_string(), node);
+}
