+fn add_slice(
+    tsymbol: &str,
+    ttype: &str,
+    tshape: &str,
+    source: &str,
+    slices: &Vec<String>,
+    egraph: &mut EGraph<TensorOp, TensorInfo>,
+    table: &mut EggSymbolTable,
+) {
+    let dtype: Dtype = ttype.into();
