+    let node = egraph.add(TensorOp::OpSlice(
+        slice_str.to_string(),
+        [*table.get(source).unwrap()],
+    ));
+    egraph.set_analysis_data(
+        node,
+        TensorInfo {
+            shape: shape.clone(),
+            dtype,
+            is_const: false,
+        },
+    );
+
+    table.insert(tsymbol.to_string(), node);
+}
