+/// A slice start is baked into the OpSlice payload here, so it must be a literal
+/// constant; a computed or parameter start has no representation in the e-graph.
+fn resolve_constant_value(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    table: &EggSymbolTable,
+    name: &str,
+) -> i64 {
+    let id = *table.get(name).expect(&format!("Symbol {} not found in table", name));
+    for en in egraph[id].nodes.iter() {
+        if let TensorOp::OpConstant(val) = en {
+            let num_str = val.split(':').next().unwrap_or(val);
+            return num_str.parse::<i64>().unwrap_or_else(|_| {
+                panic!("Slice start {} is not an integer literal: {}", name, val)
+            });
+        }
+    }
+    panic!("Slice start {} is not a constant", name);
+}
