+pub fn validate_region_exists(
+    region_name: &str,
+    regions: &std::collections::HashMap<String, HLORegion>,
+) -> bool {
+    if !regions.contains_key(region_name) {
+        panic!("Region {} does not exist", region_name);
+    }
+
+    // region only contains parameter and add/or/and/maximum instructions
+    for instruction in regions.get(region_name).unwrap().instructions.iter() {
+        match instruction {
+            HLOExpr::Parameter { .. } => {}
+            HLOExpr::BinaryOp { op_name, .. }
+                if matches!(op_name.as_str(), "add" | "or" | "and" | "maximum") => {}
+            _ => {
+                panic!(
+                    "Region {} contains instructions other than parameter/add/or/and/maximum",
+                    region_name
+                );
+            }
+        }
+    }
+    true
+}
