+// The single axis a matched reduce-add removes, from the enode payload.
+// Rank-1 reduce output only; any payload but "0" or "1" gives None.
+fn reduce_axis(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    lhs_eclasses: &Vec<Id>,
+    lhs_enodes: &Vec<Option<TensorOp>>,
+) -> Option<usize> {
+    if egraph[lhs_eclasses[1]].data.shape.len() != 1 {
+        return None;
+    }
+    let dims = match &lhs_enodes[1] {
+        Some(TensorOp::OpReduceAdd(data, _)) => data.replace(' ', ""),
+        _ => panic!("OpReduceAdd should have metadata!"),
+    };
+    match dims.as_str() {
+        "0" => Some(0),
+        "1" => Some(1),
+        _ => None,
+    }
