+// LHS postorder: ?x(0), reduce(1), reshape(2) -> 3 eclasses
+pub fn precond_13(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
