+// True if some enode tree under this eclass reaches no Var (kernel parameter).
+// Mirrors detect_constants/op_repr in extractor/utils.rs: such subtrees are folded to
+// exact HBM constants, so the lossy f32 shift decompositions must not be unioned in.
+fn is_input_free(egraph: &EGraph<TensorOp, TensorInfo>, eclass: Id, visited: &mut HashSet<Id>) -> bool {
+    // cycle guard, same stack-scoped visited set as op_repr
+    if visited.contains(&eclass) {
+        return false;
+    }
+    visited.insert(eclass);
+    let mut free = false;
+    for en in egraph[eclass].nodes.iter() {
+        // Var is a kernel parameter; DetectedConst does not exist yet during rewriting
+        if matches!(en, TensorOp::Var(_) | TensorOp::DetectedConst(_)) {
+            continue;
+        }
+        if en.children().iter().all(|c| is_input_free(egraph, *c, visited)) {
