+// Rule 20: (shift-left ?x ?y) =>
+//   (convert_? (multiply (convert_? ?x) (power (broadcast_? (constant_?)) (convert_? ?y))))
+// Decompose shift-left into multiply by power-of-2, going through f32 because NKI
+// has no shift primitive but does have multiply and power.
+// Fires only on u32/s32 shift-left (the only types that appear in TPUGraphs kernels).
+pub fn precond_20(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, _lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let dt = lhs_metadata[2].dtype;
+    if !matches!(dt, Dtype::U32 | Dtype::I32) {
+        return false;
+    }
+    // fully constant shifts stay exact via constant folding
+    !(is_input_free(egraph, lhs_eclasses[0], &mut HashSet::new())
+        && is_input_free(egraph, lhs_eclasses[1], &mut HashSet::new()))
+}
+pub fn metadata_20(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, _lhs_enodes: &Vec<Option<TensorOp>>) -> Vec<Option<String>> {
+    // RHS postorder (children before parents, leaves visited tree-left-to-right):
+    //  0: ?x
+    //  1: constant_?            -> "2:f32[]"
+    //  2: broadcast_? constant -> shape of LHS shift-left output
+    //  3: ?y
+    //  4: convert_? ?y         -> "f32"
+    //  5: power(broadcast, convert_y)
+    //  6: convert_? power      -> dtype of LHS shift-left output ("u32" or "s32")
+    //  7: multiply(?x, convert) -> the shift dtype, so it wraps as the shift does
+    let lhs_md_shift: TensorInfo = egraph[lhs_eclasses[2]].data.clone();
+    let shape_str: String = lhs_md_shift.shape.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(",");
+    let out_dtype = match lhs_md_shift.dtype {
+        Dtype::U32 => "u32",
+        Dtype::I32 => "s32",
+        _ => "u32",
+    };
+    let mut rhs_metadata = vec![None; 8];
+    rhs_metadata[1] = Some("2:f32[]".to_string());
+    rhs_metadata[2] = Some(shape_str);
+    rhs_metadata[4] = Some("f32".to_string());
+    rhs_metadata[6] = Some(out_dtype.to_string());
+    rhs_metadata
+}
+pub fn set_shapes_20(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 3);
+    assert_eq!(rhs_eclasses.len(), 8);
+    let lhs_md: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let shift_shape = lhs_md[2].shape.clone();
+    let shift_dtype = lhs_md[2].dtype;
+    // 1: constant 2.0 (scalar f32)
+    egraph.set_analysis_data(rhs_eclasses[1],
+        TensorInfo { shape: vec![], dtype: Dtype::FP32, is_const: true });
+    // 2: broadcast scalar to shift output shape
+    egraph.set_analysis_data(rhs_eclasses[2],
+        TensorInfo { shape: shift_shape.clone(), dtype: Dtype::FP32, is_const: false });
+    // 4: convert(?y) -> f32, same shape as ?y
+    egraph.set_analysis_data(rhs_eclasses[4],
+        TensorInfo { shape: lhs_md[1].shape.clone(), dtype: Dtype::FP32, is_const: false });
+    // 5: power(broadcast, convert_y) -> f32; 2^k is exact in f32 for every k
+    egraph.set_analysis_data(rhs_eclasses[5],
+        TensorInfo { shape: shift_shape.clone(), dtype: Dtype::FP32, is_const: false });
+    // 6: convert(power) -> the shift dtype, so the multiply below is integer
+    egraph.set_analysis_data(rhs_eclasses[6],
+        TensorInfo { shape: shift_shape.clone(), dtype: shift_dtype, is_const: false });
+    // 7: multiply(?x, 2^k) in the shift dtype: exact, and wraps as the shift does
+    egraph.set_analysis_data(rhs_eclasses[7],
+        TensorInfo { shape: shift_shape, dtype: shift_dtype, is_const: false });
+}
