+// Rule 24: (dot ?a ?b) => (convert_? (dot (convert_? ?a) (convert_? ?b)))
+pub fn precond_24(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, _lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+
+    // Gate on s8 so the s32 dot this produces cannot match again.
+    if lhs_metadata[2].dtype != Dtype::I8 {
+        return false;
+    }
+    for operand in &lhs_metadata[0..2] {
+        if operand.shape.len() != 2 {
+            return false;
+        }
+        // Only real s8 matrices; constant and vector operands never reach the accumulator.
+        if operand.is_const || operand.dtype != Dtype::I8 {
+            return false;
+        }
+        if operand.shape.iter().any(|&d| d == 1) {
+            return false;
+        }
+    }
+    true
