+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let mut metadata = lhs_metadata[0].shape.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(",");
+    metadata.push_str(&format!(",{:?}", lhs_metadata[0].dtype));
+
+    let mut rhs_metadata = vec![None; 4];
+    rhs_metadata[0] = Some(metadata);
+    rhs_metadata[1] = Some("0".to_string());
+    rhs_metadata
+}
+
+pub fn set_shapes_27(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 2);
+    assert_eq!(rhs_eclasses.len(), 4);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+
+    // rhs_eclasses: eye(0), reverse(eye)(1), ?x(2), dot(3)
+    egraph.set_analysis_data(rhs_eclasses[0],
+        TensorInfo { shape: lhs_metadata[0].shape.clone(), dtype: lhs_metadata[0].dtype, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[1],
+        TensorInfo { shape: lhs_metadata[0].shape.clone(), dtype: lhs_metadata[0].dtype, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[3], lhs_metadata[1].clone());
+}
+
+// Rule 28: (reverse_? ?x) => (reverse_? (reverse_? ?x))
+// Splits dims={0,1} into two single-axis reverses (rules 11/27).
+pub fn precond_28(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 2);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    if lhs_metadata[0].dtype == Dtype::U8 { return false; }
+    if lhs_metadata[0].shape != vec![16, 16] { return false; }
+    let dims = match &lhs_enodes[1] {
+        Some(TensorOp::OpReverse(data, _)) => data.replace(' ', ""),
+        _ => panic!("OpReverse should have metadata!"),
+    };
+    if dims != "0,1" { return false; }
+    true
+}
+
+pub fn metadata_28(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    lhs_eclasses: &Vec<Id>,
+    _lhs_enodes: &Vec<Option<TensorOp>>,
+) -> Vec<Option<String>> {
+    assert_eq!(lhs_eclasses.len(), 2);
+
+    // Reversing both axes is reversing each in turn; rules 11 and 27 then lower each one.
+    // Emitting the two dots directly here instead inflates the egraph enough to stall the
+    // extractor on kernels with several reverses.
+    // RHS postorder: ?x(0), reverse{1}(?x)(1), reverse{0}(...)(2)
+    let mut rhs_metadata = vec![None; 3];
+    rhs_metadata[1] = Some("1".to_string());
+    rhs_metadata[2] = Some("0".to_string());
+    rhs_metadata
+}
+
+pub fn set_shapes_28(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 2);
+    assert_eq!(rhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+
+    // Both intermediate reverses have the operand's shape and dtype.
+    egraph.set_analysis_data(rhs_eclasses[1], lhs_metadata[0].clone());
+    egraph.set_analysis_data(rhs_eclasses[2], lhs_metadata[1].clone());
+}
+
+// Rule 29: (update-slice_? ?a ?b) => ?b
+// A full-shape update covers the operand: XLA clamps starts to 0.
+pub fn precond_29(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, _lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+
+    // Update shape must equal the operand shape.
+    if lhs_metadata[1].shape.len() != lhs_metadata[0].shape.len() {
+        return false;
+    }
+    for (i, &dim) in lhs_metadata[1].shape.iter().enumerate() {
+        if dim != lhs_metadata[0].shape[i] {
+            return false;
+        }
+    }
+
+    true
+}
+
+pub fn metadata_29(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    lhs_eclasses: &Vec<Id>,
+    _lhs_enodes: &Vec<Option<TensorOp>>,
+) -> Vec<Option<String>> {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let _lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+
+    let rhs_metadata = vec![None; 1];
+    rhs_metadata
+}
+
+pub fn set_shapes_29(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 3);
+    assert_eq!(rhs_eclasses.len(), 1);
+    let _lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+}
+
+// Rule 30: (reshape_? (reduce-add_? ?x)) => (dot (broadcast_? (constant_?)) ?x)
+// The non-I32 mirror of rule 26; rule 26 is I32-only.
+pub fn precond_30(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    if lhs_metadata[0].dtype == Dtype::U8 { return false; }
+    if lhs_metadata[0].dtype == Dtype::I32 { return false; }
+    if lhs_metadata[0].is_const { return false; }
+    if lhs_metadata[0].shape.len() != 2 { return false; }
+    if reduce_axis(egraph, lhs_eclasses, lhs_enodes) != Some(0) { return false; }
+    lhs_metadata[2].shape == vec![1, lhs_metadata[0].shape[1]]
+}
+
+pub fn metadata_30(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    lhs_eclasses: &Vec<Id>,
+    _lhs_enodes: &Vec<Option<TensorOp>>,
+) -> Vec<Option<String>> {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let n = lhs_metadata[0].shape[0];
+
+    // RHS postorder: constant(0), broadcast(1), ?x(2), dot(3)
+    let mut rhs_metadata = vec![None; 4];
+    rhs_metadata[0] = Some(format!("1:{}[]", lhs_metadata[0].dtype));
+    rhs_metadata[1] = Some(format!("1,{}", n));
+    rhs_metadata
+}
+
+pub fn set_shapes_30(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 3);
+    assert_eq!(rhs_eclasses.len(), 4);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let dtype = lhs_metadata[0].dtype;
+    let n = lhs_metadata[0].shape[0];
+
+    egraph.set_analysis_data(rhs_eclasses[0],
+        TensorInfo { shape: vec![1], dtype, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[1],
+        TensorInfo { shape: vec![1, n], dtype, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[3], lhs_metadata[2].clone());
+}
+
+// Rule 31: (reshape_? (reduce-add_? ?x))
+//   => (bitcvt (reshape_? (reshape_? (bitcvt (dot (broadcast_? (constant_?)) ?x)))))
+// Rule 30 for a [K,1] output: the same bytes in a different spad tiling, relayed
+// through the HBM byte view. I8 only, since the flat reshape assumes a 1-byte element.
+pub fn precond_31(egraph: &EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, lhs_enodes: &Vec<Option<TensorOp>>) -> bool {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    if lhs_metadata[0].dtype != Dtype::I8 { return false; }
+    if lhs_metadata[0].is_const { return false; }
+    if lhs_metadata[0].shape.len() != 2 { return false; }
+    if reduce_axis(egraph, lhs_eclasses, lhs_enodes) != Some(0) { return false; }
+    lhs_metadata[2].shape == vec![lhs_metadata[0].shape[1], 1]
+}
+
+pub fn metadata_31(
+    egraph: &EGraph<TensorOp, TensorInfo>,
+    lhs_eclasses: &Vec<Id>,
+    _lhs_enodes: &Vec<Option<TensorOp>>,
+) -> Vec<Option<String>> {
+    assert_eq!(lhs_eclasses.len(), 3);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let n = lhs_metadata[0].shape[0];
+    let k = lhs_metadata[0].shape[1];
+
+    // RHS postorder: constant(0), broadcast(1), ?x(2), dot(3), bitcvt(4), reshape flat(5),
+    //                reshape out(6), bitcvt(7)
+    let mut rhs_metadata = vec![None; 8];
+    rhs_metadata[0] = Some(format!("1:{}[]", Dtype::I8));
+    rhs_metadata[1] = Some(format!("1,{}", n));
+    rhs_metadata[5] = Some(format!("{}", k));
+    rhs_metadata[6] = Some(lhs_metadata[2].shape.iter().join(","));
+    rhs_metadata
+}
+
+pub fn set_shapes_31(egraph: &mut EGraph<TensorOp, TensorInfo>, lhs_eclasses: &Vec<Id>, rhs_eclasses: &Vec<Id>) {
+    assert_eq!(lhs_eclasses.len(), 3);
+    assert_eq!(rhs_eclasses.len(), 8);
+    let lhs_metadata: Vec<TensorInfo> = lhs_eclasses.iter().map(|id| egraph[*id].data.clone()).collect();
+    let n = lhs_metadata[0].shape[0];
+    let k = lhs_metadata[0].shape[1];
+
+    egraph.set_analysis_data(rhs_eclasses[0],
+        TensorInfo { shape: vec![1], dtype: Dtype::I8, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[1],
+        TensorInfo { shape: vec![1, n], dtype: Dtype::I8, is_const: true });
+    egraph.set_analysis_data(rhs_eclasses[3],
+        TensorInfo { shape: vec![1, k], dtype: Dtype::I8, is_const: false });
+    egraph.set_analysis_data(rhs_eclasses[4],
+        TensorInfo { shape: vec![1, k], dtype: Dtype::U8, is_const: false });
+    egraph.set_analysis_data(rhs_eclasses[5],
+        TensorInfo { shape: vec![k], dtype: Dtype::U8, is_const: false });
+    egraph.set_analysis_data(rhs_eclasses[6],
+        TensorInfo { shape: lhs_metadata[2].shape.clone(), dtype: Dtype::U8, is_const: false });
+    egraph.set_analysis_data(rhs_eclasses[7], lhs_metadata[2].clone());
+}

